-- 取一本在馆副本并锁住：并发借同一本书时只会有一个成功
SELECT copy_id INTO v_copy_id FROM book_copy
 WHERE isbn = p_isbn AND status = '在馆'
 ORDER BY copy_id LIMIT 1 FOR UPDATE;
IF v_copy_id IS NULL THEN
  SET p_code = 1006, p_msg = '该书已全部借出';
  LEAVE proc;
END IF;

UPDATE book_copy SET status = '借出' WHERE copy_id = v_copy_id;
SET p_due_at = DATE_ADD(NOW(), INTERVAL 30 DAY);
INSERT INTO loan (copy_id, reader_id, borrow_at, due_at)
VALUES (v_copy_id, v_reader_id, NOW(), p_due_at);

CREATE TRIGGER trg_loan_return
AFTER UPDATE ON loan FOR EACH ROW
BEGIN
  DECLARE v_days INT;
  IF NEW.return_at IS NOT NULL AND OLD.return_at IS NULL THEN
    SET v_days = GREATEST(DATEDIFF(NEW.return_at, NEW.due_at), 0);
    IF v_days > 0 THEN
      INSERT INTO fine (loan_id, reader_id, days_overdue, amount)
      VALUES (NEW.id, NEW.reader_id, v_days, v_days * 0.20);

      UPDATE reader
         SET credit = GREATEST(CAST(credit AS SIGNED) - v_days * 2, 0),
             status = IF(GREATEST(CAST(credit AS SIGNED) - v_days * 2, 0) < 60, '冻结', status)
       WHERE id = NEW.reader_id;
    END IF;
  END IF;
END

-- 同一座位、时间段重叠检查（加锁，避免两人抢到同一时段）
SELECT COUNT(*) INTO v_conflict FROM reservation
 WHERE seat_id = p_seat_id
   AND status IN ('已预约', '已签到')
   AND start_at < p_end AND end_at > p_start
 FOR UPDATE;
IF v_conflict > 0 THEN
  SET p_code = 2005, p_msg = '该时段已被预约，换个时间或座位';
  LEAVE proc;
END IF;
